@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&family=Orbitron:wght@500;600;700;800&display=swap');
:root{--ink:#f2eee5;--muted:#a19f96;--gold:#e4bb70;--gold2:#f6dfa6;--teal:#69d9c0;--red:#e77b65;--panel:rgba(15,21,24,.76);--line:rgba(235,220,190,.18);--mono:'DM Mono',monospace;--display:'Orbitron',sans-serif;--body:'Manrope',sans-serif}
*{box-sizing:border-box}html,body{height:100%;margin:0;overflow:hidden;background:#111719;color:var(--ink);font-family:var(--body);-webkit-tap-highlight-color:transparent;touch-action:none}button{font:inherit;color:inherit}#game-shell{position:relative;width:100%;height:100%;min-height:100dvh;overflow:hidden;background:#172023}#world{position:absolute;inset:0;width:100%;height:100%;display:block;touch-action:none}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(8,13,16,.48),transparent 25%,transparent 68%,rgba(7,11,13,.64)),radial-gradient(ellipse at 50% 50%,transparent 38%,rgba(6,10,12,.37) 100%)}.topbar{height:74px;position:absolute;z-index:5;top:0;left:0;right:0;display:flex;align-items:center;padding:0 34px;border-bottom:1px solid rgba(255,255,255,.085);background:linear-gradient(180deg,rgba(10,15,17,.67),rgba(10,15,17,.18));gap:20px}.brand{display:flex;align-items:center;gap:12px;min-width:225px}.brand-mark{font-family:var(--display);font-weight:800;font-size:21px;color:#101719;width:36px;height:36px;display:grid;place-items:center;background:var(--gold);clip-path:polygon(25% 0,75% 0,100% 25%,100% 75%,75% 100%,25% 100%,0 75%,0 25%);box-shadow:0 0 24px #e4bb7040}.brand-title{font:700 12px var(--display);letter-spacing:2px}.brand-sub{font:9px var(--mono);letter-spacing:1.5px;color:#aaa99e;margin-top:3px}.realm-chip{font:10px var(--mono);letter-spacing:1.2px;color:#c5c2b8;border:1px solid rgba(255,255,255,.14);background:#10171880;padding:10px 13px;display:flex;align-items:center;gap:9px}.realm-dot,.live-dot{width:7px;height:7px;border-radius:50%;background:#dfaa63;box-shadow:0 0 10px #dfaa63;display:inline-block}.realm-divider{color:#626b6b}.icon-btn{margin-left:auto;background:#11191bc4;border:1px solid var(--line);width:36px;height:36px;border-radius:50%;color:var(--gold);font-size:18px;cursor:pointer}.hero-panel{position:absolute;z-index:3;top:104px;left:40px;width:272px;padding:0 0 17px;text-shadow:0 2px 14px #000b}.eyebrow{font:10px var(--mono);letter-spacing:1.5px;color:#c8c0ab;display:flex;align-items:center;gap:7px}.live-dot{width:6px;height:6px;background:#d7ad6a;box-shadow:0 0 9px #d7ad6a}.hero-panel h1{font:700 25px var(--display);letter-spacing:.6px;margin:12px 0 13px;line-height:1.2}.name-glow{display:block;color:var(--gold);font:500 10px var(--mono);letter-spacing:2.4px;margin-top:5px}.rank-line{display:flex;align-items:center;gap:8px;font-size:11px}.rank-label{font:9px var(--mono);letter-spacing:1px;color:#9da19b}.rank-line strong{font:700 11px var(--display);letter-spacing:1.2px;color:#e3c781}.rank-flare{color:#fff3ce}.xp-track{height:3px;background:#eee3c222;margin-top:10px;overflow:hidden}.xp-track>div{height:100%;width:0;background:linear-gradient(90deg,#bd8d4e,#f5d992);box-shadow:0 0 8px #f4d28c;transition:width .5s}.xp-caption{display:flex;justify-content:space-between;margin-top:5px;color:#aaa99e;font:8px var(--mono);letter-spacing:1px}.vitals{margin-top:13px;display:grid;gap:7px;width:238px}.vital-row{display:flex;align-items:center;gap:7px}.vital-icon{width:12px;font-size:12px}.heart{color:#e77c68}.spark{color:#8fdbca}.vital-bar{height:5px;flex:1;background:#e8e5d21c;overflow:hidden}.vital-bar div{height:100%;transition:width .22s}.health-fill{background:linear-gradient(90deg,#b34c47,#ec8872);box-shadow:0 0 9px #e27768}.essence-fill{background:linear-gradient(90deg,#3b9388,#78e0c3);box-shadow:0 0 9px #6dd6c0}.vital-row>span:last-child{font:9px var(--mono);width:23px;text-align:right;color:#ddd9cc}.quest-card{position:absolute;z-index:3;right:38px;top:101px;width:279px;padding:15px 17px 13px;background:linear-gradient(145deg,rgba(18,26,27,.88),rgba(18,24,25,.66));border:1px solid rgba(223,204,163,.22);box-shadow:0 12px 35px #0004;backdrop-filter:blur(8px)}.quest-card:before{content:'';position:absolute;left:-1px;top:0;height:100%;width:2px;background:linear-gradient(180deg,var(--gold),transparent)}.quest-kicker{display:flex;justify-content:space-between;font:9px var(--mono);letter-spacing:1.25px;color:#baa879}.quest-counter{color:#8f9994}.quest-card h2{font:600 16px var(--body);margin:10px 0 4px;letter-spacing:-.3px}.quest-card p{font-size:11px;color:#b5b6ae;margin:0 0 12px;line-height:1.5}.quest-progress{height:3px;background:#fff2;}.quest-progress div{height:100%;width:0;background:var(--teal);transition:width .35s}.quest-foot{display:flex;justify-content:space-between;margin-top:7px;font:9px var(--mono);color:#929a95}.reward{color:#89918d}.reward b{color:#ded0a5;font-weight:400}.bottom-hud{position:absolute;z-index:4;bottom:0;left:0;right:0;height:106px;display:flex;align-items:center;padding:0 38px;background:linear-gradient(0deg,rgba(9,14,16,.88),rgba(9,14,16,.47));border-top:1px solid rgba(240,230,200,.11)}.objective-hint{display:flex;align-items:center;gap:11px;min-width:260px}.hint-sigil{width:30px;height:30px;display:grid;place-items:center;border:1px solid #d5b66e6b;color:var(--gold);font-size:15px;transform:rotate(45deg)}.hint-sigil::first-letter{transform:rotate(-45deg)}.objective-hint>div{display:grid;gap:5px}.objective-hint strong{font:10px var(--display);letter-spacing:1px;color:#e0c681}.objective-hint span:not(.hint-sigil){font-size:10px;color:#a6aaa2}.controls-legend{margin-left:auto;display:flex;align-items:center;gap:7px;font:8px var(--mono);letter-spacing:.5px;color:#999f99}.controls-legend kbd{font:9px var(--mono);padding:5px 7px;border:1px solid #ffffff36;background:#ffffff0b;color:#e4e0d3;border-radius:2px;margin-left:10px}.mobile-controls{display:none}.interaction-prompt{position:absolute;z-index:5;left:50%;bottom:138px;transform:translate(-50%,8px);display:flex;align-items:center;gap:9px;background:rgba(12,18,19,.83);border:1px solid #d9c17b70;padding:8px 13px;font:9px var(--mono);letter-spacing:1.2px;color:#f0e2b9;opacity:0;transition:.18s;pointer-events:none}.interaction-prompt.show{opacity:1;transform:translate(-50%,0)}.prompt-key{color:#111819;background:var(--gold);font-weight:500;padding:3px 6px}.toast{position:absolute;z-index:8;top:48%;left:50%;transform:translate(-50%,10px);padding:11px 16px;background:#101819e8;border:1px solid #e6c87877;color:#f5e4b7;font:10px var(--mono);letter-spacing:1px;opacity:0;transition:.25s;pointer-events:none;text-align:center;max-width:90vw}.toast.show{opacity:1;transform:translate(-50%,0)}.world-labels{position:absolute;inset:0;pointer-events:none;z-index:2}.world-label{position:absolute;font:8px var(--mono);letter-spacing:1px;color:#e8d59e;text-shadow:0 1px 5px #000;background:#141a19a1;padding:4px 6px;border:1px solid #e5cb7950;white-space:nowrap;transform:translate(-50%,-100%)}.rank-up,.intro-overlay,.end-overlay{position:absolute;inset:0;z-index:12;display:grid;place-items:center;background:rgba(7,12,14,.62);backdrop-filter:blur(7px);opacity:0;pointer-events:none;transition:opacity .35s}.rank-up.show,.intro-overlay.show,.end-overlay.show{opacity:1;pointer-events:auto}.rank-up-card,.end-card{width:min(440px,90vw);padding:38px 35px;text-align:center;background:linear-gradient(150deg,#1c2929f5,#101819f7);border:1px solid #d8bd786b;box-shadow:0 25px 100px #0009;position:relative}.rank-up-card:before,.rank-up-card:after{content:'';position:absolute;width:18px;height:18px;border-color:#e4bb70;border-style:solid}.rank-up-card:before{left:8px;top:8px;border-width:1px 0 0 1px}.rank-up-card:after{right:8px;bottom:8px;border-width:0 1px 1px 0}.rank-up-symbol{color:var(--gold);font-size:33px;text-shadow:0 0 22px #efca7c;margin-bottom:12px}.rank-up-kicker,.end-kicker{font:9px var(--mono);letter-spacing:2px;color:#bdac7d}.rank-up-card h2{font:700 25px var(--display);color:#f1d996;letter-spacing:2px;margin:12px 0}.rank-up-card p{font-size:13px;color:#b5b9b0}.rank-up-card button,.intro-content button,.end-card button{margin-top:21px;background:var(--gold);color:#171b18;border:0;padding:13px 20px;font:700 10px var(--mono);letter-spacing:1.4px;cursor:pointer}.rank-up-card button span,.intro-content button span,.end-card button span{font-size:15px;margin-left:13px}.intro-overlay{z-index:15;background:radial-gradient(ellipse at center,rgba(12,20,20,.62),rgba(6,11,13,.9));text-align:center}.intro-content{padding:30px}.intro-overline{font:10px var(--mono);letter-spacing:3px;color:#d4be80}.intro-title{font:800 clamp(44px,9vw,88px)/1 var(--display);letter-spacing:4px;margin:20px 0 14px;text-shadow:0 8px 40px #000}.intro-title i,.end-card h2 i{font-style:normal;color:var(--gold)}.intro-rule{width:60px;height:1px;background:var(--gold);margin:0 auto}.intro-content p{font-size:14px;color:#d5d4cb;margin:20px 0 4px}.intro-content button{padding:15px 24px}.intro-note{margin-top:23px;color:#8f9a94;font:8px var(--mono);letter-spacing:1.5px}.end-card h2{font:800 38px/1.2 var(--display);letter-spacing:2px;margin:18px 0}.end-card p{font-size:14px;color:#bbc1b7;line-height:1.7}.final-stats{margin:18px 0;color:#d6c488;font:10px var(--mono);letter-spacing:1px}.damage-flash{position:absolute;inset:0;z-index:7;pointer-events:none;opacity:0;background:radial-gradient(ellipse,transparent 35%,rgba(202,61,49,.55));transition:opacity .12s}.damage-flash.hit{opacity:1}
@media(max-width:760px){.topbar{height:58px;padding:0 15px;gap:10px}.brand{min-width:auto;gap:8px}.brand-mark{width:30px;height:30px;font-size:17px}.brand-title{font-size:10px;letter-spacing:1.4px}.brand-sub{font-size:7px;letter-spacing:1px}.realm-chip{margin-left:auto;font-size:8px;letter-spacing:.6px;padding:8px 8px;gap:6px}.icon-btn{width:30px;height:30px;flex-shrink:0}.hero-panel{top:73px;left:16px;width:190px}.hero-panel h1{font-size:18px;margin:8px 0}.name-glow{font-size:8px;letter-spacing:1.6px}.eyebrow{font-size:8px;letter-spacing:.8px}.rank-label{font-size:8px}.rank-line strong{font-size:9px}.xp-track{margin-top:7px}.xp-caption{font-size:7px}.vitals{width:170px;margin-top:9px;gap:6px}.vital-row{gap:5px}.quest-card{right:12px;top:73px;width:min(192px,48vw);padding:10px 10px 9px}.quest-kicker{font-size:7px;letter-spacing:.7px}.quest-card h2{font-size:12px;margin:7px 0 3px}.quest-card p{font-size:9px;line-height:1.35;margin-bottom:8px}.quest-foot{font-size:7px}.reward{display:none}.bottom-hud{height:95px;padding:0 15px;align-items:flex-start;background:linear-gradient(0deg,rgba(8,13,14,.92),rgba(8,13,14,.58));}.objective-hint{min-width:0;position:absolute;left:15px;top:12px;gap:8px}.hint-sigil{width:23px;height:23px;font-size:11px}.objective-hint strong{font-size:8px}.objective-hint span:not(.hint-sigil){font-size:8px}.controls-legend{display:none}.mobile-controls{display:flex;position:absolute;inset:0;align-items:flex-end;justify-content:space-between;padding:0 16px 13px;pointer-events:none}.stick-zone{width:104px;height:88px;position:relative;pointer-events:auto;touch-action:none}.stick-base{position:absolute;left:4px;bottom:0;width:76px;height:76px;border-radius:50%;background:rgba(226,230,215,.12);border:1px solid rgba(234,232,210,.32);box-shadow:inset 0 0 14px #0004}.stick-base:after{content:'·';position:absolute;inset:0;display:grid;place-items:center;color:#fff4;font-size:30px}.stick-knob{position:absolute;width:34px;height:34px;border-radius:50%;left:20px;top:20px;background:linear-gradient(145deg,#e1c781,#ac8a4c);border:1px solid #fff9;box-shadow:0 2px 12px #0008;z-index:2;transform:translate(0,0)}.action-buttons{display:flex;align-items:flex-end;gap:11px;pointer-events:auto;padding-bottom:1px}.touch-action{border-radius:50%;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;touch-action:none;user-select:none;box-shadow:0 4px 20px #0007}.touch-action span{font-size:19px;line-height:1}.touch-action small{font:7px var(--mono);letter-spacing:.5px}.interact-action{width:49px;height:49px;background:rgba(180,156,98,.77);border:1px solid #ffebb58c;color:#fff5df}.attack-action{width:59px;height:59px;background:rgba(156,66,54,.88);border:1px solid #ffb09c99;color:#fff0e9}.interaction-prompt{bottom:111px;font-size:8px;padding:7px 10px}.toast{top:44%;font-size:9px}.world-label{font-size:7px}.intro-title{letter-spacing:1px}.intro-overline{font-size:8px;letter-spacing:1.5px}.intro-content p{font-size:12px}.intro-note{font-size:7px;line-height:1.6}.rank-up-card{padding:30px 22px}.rank-up-card h2{font-size:20px}.end-card h2{font-size:32px}}
@media(max-height:520px) and (orientation:landscape){.topbar{height:46px}.hero-panel{top:56px}.quest-card{top:56px}.bottom-hud{height:72px}.vitals{margin-top:5px}.hero-panel h1{font-size:17px}.mobile-controls{padding-bottom:6px}.stick-zone{height:67px}.stick-base{width:60px;height:60px}.stick-knob{left:13px;top:13px;width:32px;height:32px}.attack-action{width:52px;height:52px}.interact-action{width:43px;height:43px}.objective-hint{top:8px}}

import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const canvas=document.querySelector('#world');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.65)); renderer.setSize(innerWidth,innerHeight,false);
renderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.PCFSoftShadowMap;
renderer.outputColorSpace=THREE.SRGBColorSpace; renderer.toneMapping=THREE.ACESFilmicToneMapping; renderer.toneMappingExposure=1.08;
const scene=new THREE.Scene(); scene.background=new THREE.Color('#a5a998'); scene.fog=new THREE.FogExp2('#9fa496',.014);
const camera=new THREE.PerspectiveCamera(42,innerWidth/innerHeight,.1,180);
scene.add(new THREE.HemisphereLight('#d9e3d5','#4a3830',2.2));
const sun=new THREE.DirectionalLight('#ffe3b2',3.3); sun.position.set(-16,25,11); sun.castShadow=true; sun.shadow.mapSize.set(1024,1024); sun.shadow.camera.left=-28;sun.shadow.camera.right=28;sun.shadow.camera.top=28;sun.shadow.camera.bottom=-28;scene.add(sun);
const fill=new THREE.DirectionalLight('#a5d5ce',.8);fill.position.set(13,10,-16);scene.add(fill);
const world=new THREE.Group();scene.add(world);
const mat=(color,rough=.88,metal=0)=>new THREE.MeshStandardMaterial({color,roughness:rough,metalness:metal});
const groundMat=mat('#777761'), rockMat=mat('#504c43'), darkRock=mat('#383c39'), grassMat=mat('#757958'), goldMat=mat('#e2bd70',.4,.45), crystalMat=new THREE.MeshStandardMaterial({color:'#70e2cc',emissive:'#216b60',emissiveIntensity:1.6,roughness:.27,metalness:.2}), fireMat=new THREE.MeshStandardMaterial({color:'#d27b49',emissive:'#973f21',emissiveIntensity:1.5,roughness:.5});
const ground=new THREE.Mesh(new THREE.CircleGeometry(37,80),groundMat);ground.rotation.x=-Math.PI/2;ground.receiveShadow=true;world.add(ground);
const grid=new THREE.GridHelper(74,38,'#b4a47b','#968f73');grid.position.y=.018;grid.material.transparent=true;grid.material.opacity=.09;world.add(grid);
// Broken plateau rim, path stones and frontier ruins
for(let i=0;i<94;i++){const a=i/94*Math.PI*2,r=35+Math.sin(i*12.7)*1.5,h=1.7+Math.sin(i*7.2)*.7;const m=new THREE.Mesh(new THREE.DodecahedronGeometry(.8+Math.random()*1.7,0),i%4?rockMat:darkRock);m.position.set(Math.cos(a)*r,h*.35,Math.sin(a)*r);m.scale.set(1,h,1.1);m.rotation.set(Math.random(),Math.random()*2,Math.random());m.castShadow=true;m.receiveShadow=true;world.add(m)}
for(let i=0;i<68;i++){let x=(Math.random()-.5)*53,z=(Math.random()-.5)*53;if(Math.hypot(x,z)<7)continue;const stone=new THREE.Mesh(new THREE.DodecahedronGeometry(.18+Math.random()*.32,0),i%3?rockMat:grassMat);stone.position.set(x,.04,z);stone.scale.y=.35;stone.rotation.y=Math.random()*3;stone.castShadow=true;world.add(stone)}
// Ruined stone arches and monoliths
function pillar(x,z,h=4,broken=false){const base=new THREE.Mesh(new THREE.BoxGeometry(.8,h,.8),rockMat);base.position.set(x,h/2,z);base.castShadow=true;base.receiveShadow=true;world.add(base);const cap=new THREE.Mesh(new THREE.BoxGeometry(1.15,.22,1.15),darkRock);cap.position.set(x,h+(broken?-.7:.05),z);cap.rotation.z=broken?.12:0;cap.castShadow=true;world.add(cap)}
for(const p of [[-13,-8,5],[13,-9,4.4],[-14,10,3.8],[14,12,5]])pillar(...p,true);
for(let i=0;i<12;i++){const angle=i/12*Math.PI*2,x=Math.cos(angle)*9,z=Math.sin(angle)*9;const stone=new THREE.Mesh(new THREE.CylinderGeometry(.28,.42,1.2,6),i%3===0?goldMat:rockMat);stone.position.set(x,.6,z);stone.castShadow=true;world.add(stone)}
// Thorn trees, silhouettes against the ruined horizon
function tree(x,z,s=1){const trunk=new THREE.Mesh(new THREE.CylinderGeometry(.12*s,.3*s,2.4*s,5),mat('#51463a'));trunk.position.set(x,1.2*s,z);trunk.castShadow=true;world.add(trunk);for(let i=0;i<3;i++){const b=new THREE.Mesh(new THREE.ConeGeometry(.16*s,1.5*s,4),mat('#403b35'));b.position.set(x+(i-1)*.52*s,2.3*s+i*.43*s,z);b.rotation.z=(i-1)*.55;b.rotation.x=.25;world.add(b)}}
for(let i=0;i<24;i++){let a=Math.random()*Math.PI*2,r=18+Math.random()*13;tree(Math.cos(a)*r,Math.sin(a)*r,.7+Math.random()*.9)}
// ember braziers along the path
const embers=[];for(const [x,z] of [[-6,1],[6,-1],[-12,0],[12,0]]){const b=new THREE.Group();b.position.set(x,0,z);const foot=new THREE.Mesh(new THREE.CylinderGeometry(.24,.4,.7,6),darkRock);foot.position.y=.35;foot.castShadow=true;b.add(foot);const flame=new THREE.Mesh(new THREE.IcosahedronGeometry(.25,1),fireMat);flame.position.y=.95;b.add(flame);const light=new THREE.PointLight('#ff9a54',1.8,5);light.position.y=1.1;b.add(light);world.add(b);embers.push({flame,light,offset:Math.random()*8})}

const labelsEl=document.querySelector('#world-labels');const actors=[];
function makeHumanoid(name,faction,x,z,options={}){
 const g=new THREE.Group();g.position.set(x,0,z);world.add(g);
 const palette={roger:['#b79b70','#d2ae72','#293b3a'],monster:['#635b4a','#d26b4c','#363d37'],human:['#536b62','#d4b674','#a44e3f'],angel:['#d9d4bf','#a9e3dc','#9fc6b8'],devil:['#4a383b','#db8060','#a3493c'],boss:['#413534','#f1ad6d','#702e30']};const [body,accent,cloth]=palette[faction];
 const bodyM=mat(body,.74),clothM=mat(cloth),skinM=mat(accent,.55), darkM=mat('#232a29');
 function add(geo,m,x,y,z,sx=1,sy=1,sz=1){const o=new THREE.Mesh(geo,m);o.position.set(x,y,z);o.scale.set(sx,sy,sz);o.castShadow=true;o.receiveShadow=true;g.add(o);return o}
 const bodyMesh=add(new THREE.CapsuleGeometry(options.boss?.62:.4,options.boss?1.05:.75,4,8),bodyM,0,1.2,0);
 add(new THREE.SphereGeometry(options.boss?.42:.31,12,10),skinM,0,2.15,0,1,1.04,.92);
 add(new THREE.BoxGeometry(options.boss?.74:.55,.52,.52),clothM,0,.92,0);
 for(const side of [-1,1]){add(new THREE.CylinderGeometry(.12,.14,.72,7),bodyM,side*.48,1.42,0,1,1,1);const leg=add(new THREE.CylinderGeometry(.14,.11,.68,7),darkM,side*.18,.36,0);leg.userData.leg=side}
 if(faction==='monster'||faction==='boss'){for(const side of [-1,1]){const horn=add(new THREE.ConeGeometry(.12,.54,5),goldMat,side*.22,2.62,0);horn.rotation.z=side*-.3}add(new THREE.SphereGeometry(.055,8,6),fireMat,-.13,2.18,.27);add(new THREE.SphereGeometry(.055,8,6),fireMat,.13,2.18,.27)}
 if(faction==='angel'){for(const side of [-1,1]){const wing=add(new THREE.ConeGeometry(.28,1.3,5),mat('#ddd8c6'),side*.68,1.57,-.1,1,1,.48);wing.rotation.z=side*.82;wing.rotation.x=-.48}}
 if(faction==='roger'){const cape=add(new THREE.ConeGeometry(.39,.85,4),mat('#394a47'),0,.96,-.37,1,1, .32);cape.rotation.x=Math.PI;add(new THREE.TorusGeometry(.36,.065,5,12),goldMat,0,2.49,0,1,.45,1)}
 const label=document.createElement('span');label.className='world-label';label.textContent=name;labelsEl.append(label);
 const actor={name,faction,g,label,body:bodyMesh,baseY:0,alive:true,...options};actors.push(actor);return actor;
}
